/* @author MILO-GAO(高振銘)@2020 */ package page2020.view;import page2020.util.EmptyUtil;public class Value extends Content<Value> {	private String value;	public Value() {		super(ContentType.value);	}	public Value text(String text) {		this.value = text;		return this;	}	public Value value(Object value) {		if (EmptyUtil.not(value)) {			if (value instanceof String) {				this.value = (String) value;			} else {				this.value = value.toString();			}		} else {			this.value = "";		}		return this;	}	public String getValue() {		return value;	}	public void setValue(String value) {		this.value = value;	}}